//! Prepare sources only; expected inventory values are fixed, never queried from metrics.
#[path="../tests/support/metrics_source.rs"]
mod support;
use mbse_model::{stage1::*,stage1_io::{Session,execute_write},native_views::{self as v,Views},native_views_io as io};
use std::path::PathBuf;
use serde_json::json;
fn main(){
 let output=PathBuf::from(std::env::args().nth(1).expect("fresh absolute /workspace output"));assert!(output.is_absolute()&&output.starts_with("/workspace")&&!output.exists());std::fs::create_dir_all(&output).unwrap();
 let mut session=Session::new(&output).unwrap();let source=support::model();session.editor=Editor::new(source.clone(),session.editor.freshness().instance_id).unwrap();let b=support::requirements(&source);let original=support::original();let mut records=source.records.clone();records.remove(&RecordId(support::SECOND_SYSTEM));assert_eq!(records,original.records);assert_eq!(source.extensions,original.extensions);assert_eq!(source.drafts,original.drafts);assert_eq!(source.creation_drafts,original.creation_drafts);
 let raw=include_bytes!("../../../docs/parity/p36b/verification/native-02/run/analysis-final-cold-copy.mbse-views.json");let mut doc:v::Document=serde_json::from_slice(raw).unwrap();doc.profile=v::scenarios::RECOVERY_PROFILE.into();doc.binding=None;let views=Views::restore(&doc.encoded().unwrap(),&session.editor).unwrap();
 let native=output.join("native.kernspan");let job=session.begin_save(&native).unwrap();assert!(session.complete(execute_write(job)));let side=output.join("native.mbse-views.json");let mut writer=io::Io::default();let job=writer.begin(&session,&views,&side,io::Kind::Bound).unwrap();assert!(writer.complete(&session,&views,io::execute(job)));let checkpoint=session.native_checkpoint().unwrap().unwrap();let decoded=Views::decode(&std::fs::read(&side).unwrap(),&session.editor,&checkpoint).unwrap();let a=serde_json::to_value(views.document()).unwrap();let bviews=serde_json::to_value(decoded.document()).unwrap();for map in["views","occurrences","edges","typed_ports","connector_edges","activity_diagrams","state_machine_diagrams","scenario_diagrams"]{assert_eq!(a[map],bviews[map]);}
 let register=output.join("requirements.json");b.save_new(&register).unwrap();
 let expected=json!({"schema":"mbse-craft.metrics-native-fixtures/1","preparation":"Source-only construction; never queries metrics. Counts are fixed independently from the added empty System and three-requirement/five-trace topology.","native_all_records":21,"native_system_1_records":20,"native_system_60082_records":1,"native_all_systems":2,"system_60082_typed_counts":0,"all_requirements":3,"all_traces":5,"all_active":4,"all_detached":1,"selected_requirement_2":{"requirements":1,"included_traces":2,"active":2,"detached":0,"boundary_traces":2,"parent_boundaries":1},"selected_requirement_1":{"requirements":1,"included_traces":0,"boundary_traces":1,"parent_boundaries":1},"native_counters":{"model_revision":source.model_revision,"raw_version":source.raw_version,"next_id":source.next_id},"register_revision":b.register.revision,"invalid_requirement_statement":"2:statement","all_original_native_meaning_and_eight_maps_preserved":true});std::fs::write(output.join("EXPECTED.json"),serde_json::to_vec_pretty(&expected).unwrap()).unwrap();println!("Prepared source-only two-System metrics native pair and independent working register at {}",output.display());
}
